type MsgExportPrivateState struct {
	// Dump the enclave's state AS OF this chain height instead of as of now.  0 means current.
	//
	// Made possible by height bookkeeping: the height is mapped to the IAVL version committed for
	// it and the export reads that version.  This is the tool the 2026-08-09 fork had no answer
	// to -- "what did this enclave actually hold at the height where the two nodes diverged?"
	Height int64 `protobuf:"varint,1,opt,name=height,proto3" json:"height,omitempty"`
	// Return one digest per section instead of the content.  THE ONLY MODE THAT CANNOT OUTGROW THE
	// TRANSPORT: the reply is a fixed handful of rows whatever the chain has done.  Comparing two
	// enclaves is comparing these, and the content dump is only needed for a section whose digest
	// already disagreed.
	DigestOnly bool `protobuf:"varint,2,opt,name=digest_only,json=digestOnly,proto3" json:"digest_only,omitempty"`
	// Restrict the dump to this section (a field name of the export struct, e.g. "CredentialPCXYMap").
	// Empty means all of them.  This is what makes a differing section fetchable on a chain whose
	// full export no longer fits.
	Section string `protobuf:"bytes,3,opt,name=section,proto3" json:"section,omitempty"`
	// Refuse rather than return more than this many bytes of content.  0 uses the built-in default.
	// Sections are measured as they are marshalled and the whole export is abandoned as soon as the
	// running total crosses the limit, so an over-large export costs one section of memory rather
	// than all of it -- which matters inside an enclave, where the budget is EPC.
	MaxBytes uint64 `protobuf:"varint,4,opt,name=max_bytes,json=maxBytes,proto3" json:"max_bytes,omitempty"`
}

