// CANONICALIZED BEFORE HASHING, because neither of the obvious byte streams is comparable across
// nodes: rows live under STABLE-SEALED KEYS and stable sealing is per-node, and the slice sections
// are built by store iteration, so their order follows those per-node keys.  The exporters already
// unseal both key and value, and JSON sorts map keys; the remaining fix is to sort array elements.
// What is hashed is therefore the logical content, which two correct enclaves agree on and two
// diverged ones do not.
type PrivateStateSectionDigest struct {
	Name string `protobuf:"bytes,1,opt,name=name,proto3" json:"name,omitempty"`
	// Rows for a map or slice section; 1 for a scalar or a single struct.
	Rows int64 `protobuf:"varint,2,opt,name=rows,proto3" json:"rows,omitempty"`
	// Hex sha256 over the canonicalized JSON of the section.
	Sha256 string `protobuf:"bytes,3,opt,name=sha256,proto3" json:"sha256,omitempty"`
	// Bytes of that canonicalized JSON -- names the section to pull when a digest disagrees, and the
	// section to blame when a full export no longer fits.
	Bytes int64 `protobuf:"varint,4,opt,name=bytes,proto3" json:"bytes,omitempty"`
}

