// A direct bank send, put through the same AML scan as MsgTransferFunds.
//
// Separate from MsgScanTransactions because almost none of that message applies here: a transfer's
// amount is spread across Pedersen commitments and VShares that the enclave has to decrypt, whereas
// a bank send's amount is public and arrives as a plain integer.  What the two share -- the window,
// the jurisdiction lookup, the threshold table -- is shared as code inside the enclave rather than
// by forcing one message to carry both shapes.
type MsgScanBankSend struct {
	Timestamp   time.Time `protobuf:"bytes,1,opt,name=timestamp,proto3,stdtime" json:"timestamp"`
	Height      int64     `protobuf:"varint,2,opt,name=height,proto3" json:"height,omitempty"`
	SrcWalletID string    `protobuf:"bytes,3,opt,name=srcWalletID,proto3" json:"srcWalletID,omitempty"`
	DstWalletID string    `protobuf:"bytes,4,opt,name=dstWalletID,proto3" json:"dstWalletID,omitempty"`
	// One per denomination in the send.  bank SendCoins carries sdk.Coins, so a single message can
	// move several denominations at once and each needs its own market and its own fail-closed
	// pricing check.
	Coins                   []*ScanBankSendCoin     `protobuf:"bytes,5,rep,name=coins,proto3" json:"coins,omitempty"`
	Params                  Params                  `protobuf:"bytes,6,opt,name=params,proto3" json:"params"`
	CountryThresholds       []*ScanCountryThreshold `protobuf:"bytes,7,rep,name=countryThresholds,proto3" json:"countryThresholds,omitempty"`
	DefaultThresholdAttoUSD string                  `protobuf:"bytes,8,opt,name=defaultThresholdAttoUSD,proto3" json:"defaultThresholdAttoUSD,omitempty"`
	JarID                   string                  `protobuf:"bytes,9,opt,name=jarID,proto3" json:"jarID,omitempty"`
	// Set when the corresponding side is on the scanned-contract whitelist, nil otherwise.
	//
	// The KEEPER resolves this, not the enclave.  Whitelist membership and the pinned-code-ID check
	// are chain state the enclave does not hold, and the enclave has no way to ask whether an address
	// is a contract.  Passing the resolved entry keeps the enclave deciding only what it is for --
	// whether the value is reportable -- and keeps contract detection on the side that can do it.
	SrcContract *ScannedContractWhitelist `protobuf:"bytes,10,opt,name=srcContract,proto3" json:"srcContract,omitempty"`
	DstContract *ScannedContractWhitelist `protobuf:"bytes,11,opt,name=dstContract,proto3" json:"dstContract,omitempty"`
}

